data "archive_file" "lambda_zip" {
    type          = "zip"
    output_path   = "${path.module}/lambda_function.zip"
    source {
      filename = "${basename(local.source_files[0])}"
      content  = file("${local.source_files[0]}")
    }
    source {
      filename = "${basename(local.source_files[1])}"
